export type DirNode = {
	/**  末段目录名 */
	name: string,
	/**  相对 root 的 POSIX 路径（`/` 分隔） */
	path: string,
	/**  子树内被识别文件数 */
	files: number,
	/**  子树内代码行合计 */
	code: number,
	/**  子树内注释行合计 */
	comments: number,
	/**  子树内空行合计 */
	blanks: number,
	/**  直接子目录与直接文件叶（≤ depth 截断；目录在前、文件在后，各按 name 字典序） */
	children: TreeEntry[],
};

/**  单篇 explore 笔记内容（纯文本 DTO，命令层直出，不套 change 域产物信封）。 */
export type ExploreDoc = {
	/**  笔记名（= 文件 stem） */
	name: string,
	/**  UTF-8 文本内容 */
	content: string,
};

/**
 *  explore 清单记录（workspace 维度，落所属 workspace 的独立 db 文件
 *  `workspaces/` 子树，`root` 即归属键，与名下会话链同库——级联删除与链还原
 *  同实例收敛）：内容唯一真源在磁盘笔记文件（由 agent 会话流程懒创建），记录
 *  是身份、文件是可丢弃投影——文件被删记录保留，未落盘记录照常存在（数据三
 *  分：记录 / 内容 / 对话）。独立主键与文件名解耦：文件改名经 in-place 改
 *  `name` 保主键，会话链绑定不破。
 * 
 *  时间戳均为 UTC unix 毫秒 `i64`，与 [`WorkspaceRecord`] 同口径。
 */
export type ExploreRecord = {
	/**  记录 id（主键，写事务内 max+1 分配；身份与文件名解耦） */
	id: number,
	/**  workspace 归属（canonical root，与 `WorkspaceRecord.root` 同口径） */
	root: string,
	/**  展示名（= 笔记文件 stem，磁盘寻址键） */
	name: string,
	/**  建档时间（UTC unix 毫秒） */
	createdAt: number,
	/**  最近更新时间（UTC unix 毫秒） */
	updatedAt: number,
};

/**  导入扫描条目：stem 名称 + 可得的修改时间。 */
export type ExploreScanEntry = {
	/**  笔记名（= 文件 stem） */
	name: string,
	/**  修改时间（UTC unix 毫秒）；metadata 不可得时为 `None` */
	modifiedAt: number | null,
};

/**  一条日志式文件清单（线面）。 */
export type FileLogEntry = {
	op: FileLogOp,
	scope: string,
	attempt: number | null,
	path: string,
	at: string | null,
};

/**  file_log 记录的文件操作。 */
export type FileLogOp = "write" | "delete" | "revert";

/**
 *  文件叶节点：单个被解析文件的行统计；父目录在深度内时挂其 `children`
 *  （目录级数 0 = 根层直属文件挂树顶层），深度外的文件不出叶（仅并入祖先聚合）。
 */
export type FileNode = {
	/**  文件名（含扩展名） */
	name: string,
	/**  相对 root 的 POSIX 路径（`/` 分隔） */
	path: string,
	/**  代码行 */
	code: number,
	/**  注释行 */
	comments: number,
	/**  空行 */
	blanks: number,
};

/**  桥接后的前端信号载荷（与 `FileWatchSignal` 同构，camelCase；无内容字节）。 */
export type FileWatchEvent = {
	/**  被修改目标的订阅路径 */
	path: string,
};

/**  中断留档（线面）。 */
export type InterruptedEntry = {
	phase: string,
	attempt: number,
	startAt: string | null,
	endAt: string | null,
};

/**
 *  三代结构代际：v2（现在）/ v1（中期）/ v0（早期）。
 * 
 *  判定规则见 `crate::parse::detect_inventory`，这里只承载结果。
 */
export type Inventory = 
/**  有 workflow.json 且含 file_log */
"v2" | 
/**  有 workflow.json 无 file_log */
"v1" | 
/**  无 workflow.json，仅 markdown 产物 */
"v0";

/**
 *  单语言统计行：`name` 取 tokei `LanguageType::name()`；`share` 为代码行份额
 *  （该语言 code / Σ全部语言 code，百分点 0–100；Σcode 为 0 时 0.0）。
 */
export type LanguageStats = {
	/**  语言名（tokei 识别名，如 "Rust" / "Markdown"） */
	name: string,
	/**  该语言被识别文件数 */
	files: number,
	/**  代码行 */
	code: number,
	/**  注释行 */
	comments: number,
	/**  空行 */
	blanks: number,
	/**  代码行份额（百分点 0–100，与排序键同轴） */
	share: number | null,
};

/**  模型清单一行：模型名 + 记录计数（计数 0 也列出）。 */
export type ModelInfo = {
	/**  模型名（查看器展示与 `Store::scan` 入参同源） */
	name: string,
	/**  记录计数 */
	count: number,
};

/**  一站流水线：该 phase 的全部 attempt 序列。 */
export type PhaseEntry = {
	phase: string,
	attempts: AttemptRecord[],
};

/**  记录信封：key / value 均为 JSON 值（native_db 类型不越信封，无二进制）。 */
export type RecordEnvelope = {
	/**  记录主键的 JSON 形态 */
	key: unknown,
	/**  记录本体（serde 转 JSON 值） */
	value: unknown,
};

/**
 *  树条目信封（tag `kind` 判别，`AgentRunMessage` 同式）：目录节点与文件叶
 *  双变体，前端以 `kind` 收窄行形态（目录可展开、文件叶不可）。
 */
export type TreeEntry = 
/**  目录节点（子树聚合统计，可展开） */
{ kind: "dir"; node: DirNode } | 
/**  文件叶（单文件行统计，不可展开） */
{ kind: "file"; node: FileNode };

/**  评估 verdict。条目级严格：非法值触发该条降级跳过。 */
export type Verdict = "pass" | "fail";

/**
 *  user 维度注册表一行（落全局库 `desktop-global.redb`，见 desktop-data-dimensions）：
 *  主键即 `root`（canonical 完整路径）。
 * 
 *  时间戳为 UTC unix 毫秒 `i64`——零解析零格式歧义，且 store 不引入 time 依赖。
 */
export type WorkspaceRecord = {
	/**  canonical 完整路径（主键） */
	root: string,
	/**  目录名最后一段（展示用；完整路径悬停展示） */
	name: string,
	/**  入库时间（UTC unix 毫秒） */
	addedAt: number,
};

